def transform(grid):
    out=[row[:] for row in grid]
    H=len(grid); W=len(grid[0])
    for color in (2,5):
        remaining={(r,c) for r in range(H) for c in range(W) if grid[r][c]==color}
        while remaining:
            seed=remaining.pop(); stack=[seed]; cells=[seed]
            while stack:
                r,c=stack.pop()
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        q=(r+dr,c+dc)
                        if q in remaining:
                            remaining.remove(q); stack.append(q); cells.append(q)
            for r,c in cells: out[r][c]=7
            r0=min(r for r,c in cells); r1=max(r for r,c in cells)
            c0=min(c for r,c in cells); c1=max(c for r,c in cells)
            cr=(r0+r1)//2
            cc=(c0+c1)//2 if c1-c0==r1-r0 else c0
            radius=max(abs(r-cr)+abs(c-cc) for r,c in cells)
            newradius=radius-1 if color==2 else radius+1
            newcells=[(r,c) for r in range(H) for c in range(W) if abs(r-cr)+abs(c-cc)==newradius]
            if color==5 and len(cells)<4*radius:
                newcells+=cells
            for r,c in newcells: out[r][c]=color
    return out

